  '1.523': `-- Migration 1.523: RPC to let a joined member update their own display name
-- Token-authenticated: only the member who owns the token can change their name

CREATE OR REPLACE FUNCTION update_member_display_name(p_token text, p_display_name text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  UPDATE sharing_members
  SET display_name = p_display_name
  WHERE token_hash = encode(digest(p_token, 'sha256'), 'hex')
    AND joined_at IS NOT NULL
    AND revoked_at IS NULL;
END;
$$;

INSERT INTO settings (key, value, updated_at) VALUES ('schema_version', '1.523', now())
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
`,

  '1.560': `-- Migration 1.560: drop plaintext token/remote_anon_key from joined_groups
-- Since 1.397 the app stores only encrypted versions (token_ciphertext/token_iv,
-- remote_anon_key_ciphertext/remote_anon_key_iv). The plaintext columns were
-- already set to NULL by the app; remove them entirely.

ALTER TABLE joined_groups DROP COLUMN IF EXISTS token;
ALTER TABLE joined_groups DROP COLUMN IF EXISTS remote_anon_key;

-- Bump schema version
INSERT INTO settings (key, value, updated_at) VALUES ('schema_version', '1.560', now())
  ON CONFLICT (key) DO UPDATE SET value = '1.560', updated_at = now();
`,

  '1.573': `-- Migration 1.573: Move list shortnames from settings accessor to a proper column
-- Aligns lists with todo_categories / habit_categories / vestiaire_categories / flashcard_decks
-- which all have a shortname TEXT column directly.

-- Add the column
ALTER TABLE lists ADD COLUMN IF NOT EXISTS shortname TEXT;

-- Backfill from settings JSON (key = 'list_shortnames', value is {"<list_id>": "<shortname>", ...})
-- jsonb_each_text returns values as plain text directly
UPDATE lists SET shortname = (
  SELECT je.value FROM settings s, jsonb_each_text(s.value::jsonb) je
  WHERE s.key = 'list_shortnames' AND je.key = lists.id::text LIMIT 1
) WHERE EXISTS (
  SELECT 1 FROM settings s, jsonb_each_text(s.value::jsonb) je
  WHERE s.key = 'list_shortnames' AND je.key = lists.id::text
);

-- Remove the dead settings key
DELETE FROM settings WHERE key = 'list_shortnames';

-- Bump schema version
INSERT INTO settings (key, value, updated_at) VALUES ('schema_version', '1.573', now())
  ON CONFLICT (key) DO UPDATE SET value = '1.573', updated_at = now();
`,

